<template><section class="page"><header><div><h2>故障报修</h2><p>拍照提交校园设施故障，并实时跟踪派单与维修进度。</p></div><el-button type="primary" @click="openCreate">我要报修</el-button></header><el-tabs v-model="tab" @tab-change="load"><el-tab-pane label="我的报修" name="mine"/><el-tab-pane label="我的维修工单" name="assigned"/></el-tabs><el-table :data="rows" border><el-table-column prop="orderNo" label="报修单号" min-width="170"/><el-table-column prop="title" label="故障" min-width="180"/><el-table-column prop="location" label="位置" min-width="160"/><el-table-column label="状态" width="130"><template #default="{row}"><el-tag>{{statusLabels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column prop="technicianName" label="维修人员" width="110"/><AdaptiveActionColumn label="操作" :width="280"><template #default="{row}"><div class="actions"><el-button link @click="openDetail(row)">详情</el-button><template v-if="tab==='assigned'"><el-button v-if="row.status==='DISPATCHED'" link type="primary" @click="act(row,'accept')">接单</el-button><el-button v-if="['ACCEPTED','WAITING_MATERIAL'].includes(row.status)" link type="primary" @click="act(row,'start')">开始维修</el-button><el-button v-if="['ACCEPTED','IN_PROGRESS','WAITING_MATERIAL'].includes(row.status)" link @click="openMaterial(row)">申请物料</el-button><el-button v-if="['IN_PROGRESS','WAITING_MATERIAL'].includes(row.status)" link type="success" @click="openComplete(row)">维修完成</el-button></template><template v-else><el-button v-if="row.status==='COMPLETED'" link type="success" @click="openClose(row)">确认关闭</el-button><el-button v-if="['PENDING_DISPATCH','DISPATCHED'].includes(row.status)" link type="danger" @click="cancel(row)">取消</el-button></template></div></template></AdaptiveActionColumn></el-table><el-pagination v-model:current-page="pageNo" v-model:page-size="pageSize" :total="total" layout="total, prev, pager, next" @current-change="load"/>
<el-dialog v-model="createDialog" title="提交故障报修" width="640px"><el-form label-width="100px"><el-form-item label="故障标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="故障分类"><el-select v-model="form.category" style="width:100%"><el-option v-for="(label,value) in categoryLabels" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="紧急程度"><el-select v-model="form.urgency"><el-option v-for="(label,value) in urgencyLabels" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="故障位置"><el-input v-model="form.location"/></el-form-item><el-form-item label="故障描述"><el-input v-model="form.description" type="textarea" :rows="4"/></el-form-item><el-form-item label="联系人"><el-input v-model="form.contactName"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactPhone"/></el-form-item><el-form-item label="故障照片"><el-upload :auto-upload="false" accept="image/*" :limit="6" :on-change="changeReportFiles" :on-remove="changeReportFiles" list-type="picture-card"><el-icon><Plus/></el-icon></el-upload></el-form-item></el-form><template #footer><el-button @click="createDialog=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submit">提交报修</el-button></template></el-dialog>
<el-dialog v-model="completeDialog" title="维修完成" width="560px"><el-input v-model="completeNote" type="textarea" :rows="4" placeholder="填写维修结果"/><el-upload style="margin-top:14px" :auto-upload="false" accept="image/*" :limit="6" :on-change="changeCompletionFiles" :on-remove="changeCompletionFiles" list-type="picture-card"><el-icon><Plus/></el-icon></el-upload><template #footer><el-button @click="completeDialog=false">取消</el-button><el-button type="primary" :loading="submitting" @click="complete">提交完工</el-button></template></el-dialog>
<el-dialog v-model="materialDialog" title="申请维修物料" width="680px"><el-select v-model="materialForm.materialId" filterable placeholder="选择物料" style="width:70%"><el-option v-for="m in materialOptions" :key="m.id" :value="m.id" :label="`${m.materialName}（可用 ${m.availableQuantity}${m.unit}）`"/></el-select><el-input-number v-model="materialForm.quantity" :min="0.001" :precision="3"/><el-input v-model="materialForm.remark" type="textarea" placeholder="申请说明" style="margin-top:14px"/><template #footer><el-button @click="materialDialog=false">取消</el-button><el-button type="primary" @click="requestMaterial">提交申请</el-button></template></el-dialog>
<el-dialog v-model="closeDialog" title="确认维修结果" width="500px"><el-form label-width="80px"><el-form-item label="评分"><el-rate v-model="closeForm.rating"/></el-form-item><el-form-item label="评价"><el-input v-model="closeForm.comment" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="closeDialog=false">取消</el-button><el-button type="primary" @click="close">确认关闭</el-button></template></el-dialog>
<el-drawer v-model="detailDialog" title="报修详情" size="580px"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="报修单号">{{detail.orderNo}}</el-descriptions-item><el-descriptions-item label="状态">{{statusLabels[detail.status]}}</el-descriptions-item><el-descriptions-item label="位置">{{detail.location}}</el-descriptions-item><el-descriptions-item label="描述">{{detail.description}}</el-descriptions-item><el-descriptions-item label="维修人员">{{detail.technicianName||'等待派单'}}</el-descriptions-item><el-descriptions-item label="维修结果">{{detail.completionNote||'-'}}</el-descriptions-item></el-descriptions><el-timeline style="margin-top:20px"><el-timeline-item v-for="e in detail.events" :key="e.createTime+e.eventType" :timestamp="dateTime(e.createTime)">{{e.remark||e.eventType}}</el-timeline-item></el-timeline></template></el-drawer></section></template>
<script setup>
import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{Plus}from'@element-plus/icons-vue';import{uploadManagedFile}from'../../../api/admin';import{acceptRepairOrder,assignedRepairOrders,availableMaterials,cancelMyRepairOrder,closeRepairOrder,completeRepairOrder,createRepairOrder,myRepairOrderDetail,myRepairOrders,requestRepairMaterials,startRepairOrder}from'../api';import{categoryLabels,dateTime,statusLabels,urgencyLabels}from'../labels'
const tab=ref('mine'),rows=ref([]),pageNo=ref(1),pageSize=ref(20),total=ref(0),createDialog=ref(false),completeDialog=ref(false),materialDialog=ref(false),closeDialog=ref(false),detailDialog=ref(false),submitting=ref(false),selected=ref(null),detail=ref(null),reportFiles=ref([]),completionFiles=ref([]),completeNote=ref(''),materialOptions=ref([]);const form=reactive({title:'',category:'ELECTRICAL',description:'',location:'',urgency:'NORMAL',contactName:'',contactPhone:'',dispatchMode:'AUTO'}),materialForm=reactive({materialId:'',quantity:1,remark:''}),closeForm=reactive({rating:5,comment:''})
const load=async()=>{const fn=tab.value==='mine'?myRepairOrders:assignedRepairOrders;const r=await fn({page:pageNo.value-1,size:pageSize.value});rows.value=r.data.content;total.value=r.data.totalElements};const openCreate=()=>{Object.assign(form,{title:'',category:'ELECTRICAL',description:'',location:'',urgency:'NORMAL',contactName:'',contactPhone:'',dispatchMode:'AUTO'});reportFiles.value=[];createDialog.value=true};const changeReportFiles=(_,files)=>reportFiles.value=files;const changeCompletionFiles=(_,files)=>completionFiles.value=files
const submit=async()=>{if(!reportFiles.value.length)return ElMessage.warning('请至少上传一张故障照片');submitting.value=true;try{const ids=[];for(const item of reportFiles.value){const r=await uploadManagedFile(item.raw);ids.push(r.data.id)}await createRepairOrder({...form,reportFileIds:ids});ElMessage.success('报修提交成功');createDialog.value=false;load()}finally{submitting.value=false}}
const act=async(row,type)=>{await(type==='accept'?acceptRepairOrder(row.id):startRepairOrder(row.id));ElMessage.success(type==='accept'?'接单成功':'已开始维修');load()};const openComplete=row=>{selected.value=row;completeNote.value='';completionFiles.value=[];completeDialog.value=true};const complete=async()=>{if(!completeNote.value.trim()||!completionFiles.value.length)return ElMessage.warning('请填写维修结果并上传完工照片');submitting.value=true;try{for(const item of completionFiles.value)await uploadManagedFile(item.raw,'FACILITY_REPAIR_COMPLETION',selected.value.id);await completeRepairOrder(selected.value.id,completeNote.value);ElMessage.success('已提交完工');completeDialog.value=false;load()}finally{submitting.value=false}}
const openMaterial=async row=>{selected.value=row;const r=await availableMaterials({page:0,size:100});materialOptions.value=r.data.content.filter(x=>x.status==='ACTIVE'&&x.availableQuantity>0);Object.assign(materialForm,{materialId:'',quantity:1,remark:''});materialDialog.value=true};const requestMaterial=async()=>{if(!materialForm.materialId)return ElMessage.warning('请选择物料');await requestRepairMaterials({repairOrderId:selected.value.id,remark:materialForm.remark,items:[{materialId:materialForm.materialId,quantity:materialForm.quantity}]});ElMessage.success('物料申请已提交');materialDialog.value=false;load()};const openClose=row=>{selected.value=row;Object.assign(closeForm,{rating:5,comment:''});closeDialog.value=true};const close=async()=>{await closeRepairOrder(selected.value.id,closeForm);ElMessage.success('工单已关闭');closeDialog.value=false;load()};const cancel=async row=>{const{value}=await ElMessageBox.prompt('请填写取消原因','取消报修');await cancelMyRepairOrder(row.id,value);ElMessage.success('已取消');load()};const openDetail=async row=>{detail.value=(await myRepairOrderDetail(row.id)).data;detailDialog.value=true};onMounted(load)
</script><style scoped>.page{padding:24px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}h2{margin:0 0 6px}p{margin:0;color:#84909a}.el-pagination{margin-top:10px;justify-content:flex-end}.actions{display:flex;flex-wrap:nowrap;white-space:nowrap}.el-upload-list{margin-top:10px}</style>
